import json
d=json.load(open('/tmp/plugins.json'))
def walk(o,path=""):
    if isinstance(o,dict):
        if 'id' in o and ('status' in o or 'enabled' in o or 'origin' in o):
            yield o
        for k,v in o.items(): yield from walk(v,path+"/"+k)
    elif isinstance(o,list):
        for v in o: yield from walk(v,path)
