  // === 階段二（2026-08-05 新增，依 knowledges/2026-07-24_小龍蝦紀律移植計劃 執行）===
  // 三條都帶 scope:['main']，只對教練自己的小龍蝦（Telegram bot_main + LINE 龍蝦小助教）
  // 生效，先觀察一週確認沒有誤觸發、沒有干擾對話，穩定後再考慮開放給 bni_tainan。
  // 分階段是計劃書第四節寫死的做法，不是保守——public agent 每天服務真實會員，
  // 一條規則誤觸發就是幾十個人看到莫名其妙的系統提示。
  { scope: ['main'], re: /提醒我|叫我起床|每天早上|每天晚上|每週|每個月|定時|排程|定期|cron|自動跑|固定時間/i, msg: 'E09（Cron 驗證鐵律）：建立排程的同一次操作，必須同步建立腳本並立即實測跑一次，不能只建 cron 就說完成。設定完當場驗證，之後定期看 log 確認沒有 fail；發現 cron 在跑但腳本不存在，馬上補，不等。' },
  { scope: ['main'], re: /記住|記下來|寫進記憶|存起來|以後都|下次要|你搞錯|不是這樣|搞錯了|更好的方法|過時了|已經改了/, msg: 'E12（記憶寫入雙鐵律）：①該不該記不靠當下心情，靠六條清單——指令失敗／教練當場糾正／教練要一個不存在的功能／外部服務失敗／發現既有記憶已過時／發現更好的做法，命中任一條就直接記。②寫進記憶前先做敏感資料檢查：含密碼／API Key／Token／身分證／完整帳號憑證就先遮蔽或抽到權限受限的檔案，不能想說「反正之後會發現」。' },
  { scope: ['main'], re: /守則第|第\s*\d+\s*條|你之前說|你上次說|我記得你說|你說過|原話|當初講的|你答應/, msg: 'E08（引用查證鐵律）：要引用守則就先查 特助心法.md 原文確認編號跟每個字；要引用過去對話就先查原始記錄確認真的說過，有 commit hash 才能講「我之前說過」。不確定就直接說「我不確定，需要查證」，不臆測、不捏造。' },
];

// === 語音訊息糾偏（E07，2026-07-24新增）===
// 不用關鍵字猜「陌生詞彙」(regex做不到語意判斷)，改用OpenClaw event本身的
// transcript/mediaType欄位——只要這則訊息是語音轉文字來的，就提醒糾偏四情況，
// 比猜關鍵字更精準（案例來源：BNI大台南會員多用LINE語音輸入，語音辨識容易諧音錯字）
function isVoiceMessage(c) {
  return !!(c && (c.transcript || c.mediaType === 'audio' || c.mediaType === 'voice'));
}
const VOICE_CORRECTION_MSG = 'E07（語音糾偏必問不猜）：這則是語音轉文字訊息，若上下文接不上、詞不達意、詞彙陌生、邏輯反常，四種情況任一出現就主動問「您說的是『XXXX』嗎？」，確認後再處理，不照字面瞎猜。';

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;
  if (!event.context || typeof event.context !== 'object') return;

  const text = extractText(event);
  const isVoice = isVoiceMessage(event.context);

  // 抓不到文字、也不是語音訊息：dump 結構供精準化，靜默退出（不壞事）
  if (!text && !isVoice) { probeDump(event, ''); return; }

  const hits = [];
  if (text) for (const r of RULES) if (r.re.test(text)) hits.push('• ' + r.msg);
  if (isVoice) hits.push('• ' + VOICE_CORRECTION_MSG);

  if (hits.length === 0) return;

  // 命中時記錄一筆，確認 hook 真的有在運作 + 抓到文字
  probeDump(event, text);

  const injection = [
    '🌱 守則提醒（系統自動對照 trigger_index）：',
    ...hits,
    '（對照後再回應教練；引用守則前先查 特助心法.md 原文確認一字不差。）',
  ].join('\n');

  if (!event.context.inject) event.context.inject = [];
  if (Array.isArray(event.context.inject)) {
    event.context.inject.push({ role: 'system', content: injection });
  }
};

module.exports = handler;
module.exports.default = handler;

