"use strict";

// OpenClaw Hook：rule-reminder
// 用途：小龍蝦跟教練對話時，每則訊息自動偵測關鍵字、注入相關「特助守則」提醒。
//       軍師版（Claude Code）pre_task_hook.sh 的 OpenClaw 對應版本，讓守則對照
//       「不靠模型記得、靠系統強制」。
// 事件：message:preprocessed（照 context-overflow-guard / bot-relay-inbound 模板）
// 注入：event.context.inject.push({ role:'system', content })
// 軍師建立 2026-05-27（教練拍板「讓小龍蝦也用這套嚴謹邏輯」）

const fs = require('fs');
const path = require('path');

const PROBE_LOG = path.join(process.env.HOME, '.openclaw', 'logs', 'rule-reminder-probe.log');

// === agentId 動態解析（2026-08-05 階段二新增）===
// 直接沿用 bot-relay-inbound v2.5 已驗證過的三層 fallback 寫法，不重新發明：
// message:preprocessed 的 ctx.agentId 可能 undefined，要能退回 sessionKey 解析。
// ⚠️ 案例56 教訓：LINE default 帳號（龍蝦小助教）綁在 main agent，
//    它的 sessionKey 是 agent:main:line:...，所以這裡拿到的一律是 "main"，
//    這正是我們要的——scope:['main'] 涵蓋教練自己的 Telegram + 龍蝦小助教。
function resolveAgentId(event) {
  const ctx = (event && event.context) ? event.context : {};
  const raw =
    event.agentId ||
    ctx.agentId ||
    (ctx.agent && ctx.agent.id) ||
    ctx.agent ||
    '';
  if (raw) return String(raw).toLowerCase();
  const sessionKey = event.sessionKey || ctx.sessionKey || '';
  if (sessionKey) {
    const parts = String(sessionKey).split(':');
    if (parts[0] === 'agent' && parts[1]) return parts[1].toLowerCase();
  }
  return 'unknown';
}

// === 防禦性多路徑抽取教練訊息文字 ===
// OpenClaw minified 源碼未明確暴露當前訊息欄位，故嘗試所有常見路徑；
// 抓不到時 dump 結構到 probe log，供事後精準化。
function extractText(event) {
  const c = (event && event.context) || {};
  const cands = [
    event.text,
    c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.body, c.userMessage,
    (c.message && (typeof c.message === 'string' ? c.message : (c.message.text || c.message.content))),
  ];
  const pickLast = (arr) => {
    if (Array.isArray(arr) && arr.length) {
      const last = arr[arr.length - 1];
      if (typeof last === 'string') return last;
      if (last && typeof last === 'object') return last.text || last.content || '';
    }
    return '';
  };
  cands.push(pickLast(event.messages));
  cands.push(pickLast(c.messages));
  for (const v of cands) if (typeof v === 'string' && v.trim()) return v;
  return '';
}

// === 偵測：記錄 event 結構（只記 keys + 短樣本，不存完整隱私）===
function probeDump(event, matchedText) {
  try {
    const c = (event && event.context) || {};
    const info = {
      ts: new Date().toISOString(),
      type: event.type,
      action: event.action,
      topKeys: Object.keys(event || {}),
      ctxKeys: Object.keys(c),
      messagesLen: Array.isArray(event.messages) ? event.messages.length : null,
      textPreview: matchedText ? String(matchedText).slice(0, 50) : '(抓不到文字)',
    };
    fs.appendFileSync(PROBE_LOG, JSON.stringify(info) + '\n');
  } catch (e) { /* silent */ }
}

// === 關鍵字 → 守則對照（翻譯自 pre_task_hook.sh，依 trigger_index.md）===
const RULES = [
  { re: /就這樣|按這樣|照這樣|算了|不做了|你決定|你看著辦|你覺得呢/, msg: '守則#08（花時間討論就是為了執行）：教練已給方向，直接執行，不再問「要做嗎」。' },
  { re: /做好了|完成了|做完|搞定|弄好了|處理好/, msg: '守則#05（凡走過必留痕跡）：口頭完成不算數，當場 commit + 給 hash 才算。' },
  { re: /對不起|抱歉|有問題|壞了|不行|出錯|錯誤|失敗|沒反應|當機/, msg: '守則#04（解決問題比解釋問題更重要）：先修好，再說原因，別只道歉。' },
  { re: /找不到|搜尋不到|找不著|沒看到|不見了/, msg: '守則#02（錯誤的地圖找不到正確位置）：先問「我是不是找錯方向了？」' },
  { re: /你又問|你又忘|怎麼又|記不住|說過了|講過了|提醒過/, msg: '守則#01（在乎=記住用戶說的話）：馬上記住並寫入 memory，下次不再犯。' },
  { re: /終端機|桌面版|手機|電報|Telegram|VPS|哪台|哪個環境|哪個介面/, msg: '守則#17（用戶環境確認）：先確認哪個介面/設備，終端機≠手機≠VPS。' },
  { re: /就像|好比|比喻|故事|小說|電影|連續劇|武俠|掌門|師兄|師弟|師妹/, msg: '守則#13（顧客的聲音=存在價值）：教練的比喻是線索，記錄並分析背後含義。' },
  { re: /為什麼|為何|原因|目的|意義何在/, msg: '守則#09（知道為什麼才有判斷力）：先確認目的，回到使命/願景/信念判斷。' },
  { re: /上傳|部署|deploy|github|上線|發布/i, msg: '守則#04（交付前驗證）：上線/部署後先用 curl 檢測 HTTP 200，再說「完成」。' },
  { re: /複製|貼上|回傳|幫我貼|拿給我/, msg: '守則#12（拒絕當資訊搬運工）：自己處理，不叫教練複製貼上回傳。' },
  { re: /太複雜|搞不懂|不要那麼麻煩|簡單一點/, msg: '守則#16（複雜的解法不一定正確）：先問「您想要什麼結果？」用最簡單的路徑。' },
  // 2026-07-24 新增：研究mattpocock/skills後，把軍師/特助側engineering-verification-discipline
  // 技能的核心教訓移植進來——案例52(三機誤報)/案例53(HEARTBEAT假旗標)都是小龍蝦自己的心跳/監控
  // 邏輯犯的錯，根因都是「信了中繼資料/衍生旗標,沒查真相源」
  { re: /連續.*天沒有|好幾天沒|一直沒有|從來沒有|好像斷了|是不是壞了|是不是掛了|沒有動靜|沒有更新|查無.*紀錄/, msg: 'E-verify（真相源驗證，2026-07-24新增）：這個判斷是不是來自中繼檔案/衍生旗標？案例52/53都是信了間接資料才誤判——先用最直接的真相源(API實測/git log/原始檔案)驗證一次，再下結論。' },

  // === 階段二（2026-08-05 新增，依 knowledges/2026-07-24_小龍蝦紀律移植計劃 執行）===
  // 三條都帶 scope:['main']，只對教練自己的小龍蝦（Telegram bot_main + LINE 龍蝦小助教）
  // 生效，先觀察一週確認沒有誤觸發、沒有干擾對話，穩定後再考慮開放給 bni_tainan。
  // 分階段是計劃書第四節寫死的做法，不是保守——public agent 每天服務真實會員，
  // 一條規則誤觸發就是幾十個人看到莫名其妙的系統提示。
  { scope: ['main'], re: /提醒我|叫我起床|每天早上|每天晚上|每週|每個月|定時|排程|定期|cron|自動跑|固定時間/i, msg: 'E09（Cron 驗證鐵律）：建立排程的同一次操作，必須同步建立腳本並立即實測跑一次，不能只建 cron 就說完成。設定完當場驗證，之後定期看 log 確認沒有 fail；發現 cron 在跑但腳本不存在，馬上補，不等。' },
  { scope: ['main'], re: /記住|記下來|寫進記憶|存起來|以後都|下次要|你搞錯|不是這樣|搞錯了|更好的方法|過時了|已經改了/, msg: 'E12（記憶寫入雙鐵律）：①該不該記不靠當下心情，靠六條清單——指令失敗／教練當場糾正／教練要一個不存在的功能／外部服務失敗／發現既有記憶已過時／發現更好的做法，命中任一條就直接記。②寫進記憶前先做敏感資料檢查：含密碼／API Key／Token／身分證／完整帳號憑證就先遮蔽或抽到權限受限的檔案，不能想說「反正之後會發現」。' },
  { scope: ['main'], re: /守則第|第\s*\d+\s*條|你之前說|你上次說|我記得你說|你說過|原話|當初講的|你答應/, msg: 'E08（引用查證鐵律）：要引用守則就先查 特助心法.md 原文確認編號跟每個字；要引用過去對話就先查原始記錄確認真的說過，有 commit hash 才能講「我之前說過」。不確定就直接說「我不確定，需要查證」，不臆測、不捏造。' },
];

// === 語音訊息糾偏（E07，2026-07-24新增）===
// 不用關鍵字猜「陌生詞彙」(regex做不到語意判斷)，改用OpenClaw event本身的
// transcript/mediaType欄位——只要這則訊息是語音轉文字來的，就提醒糾偏四情況，
// 比猜關鍵字更精準（案例來源：BNI大台南會員多用LINE語音輸入，語音辨識容易諧音錯字）
function isVoiceMessage(c) {
  return !!(c && (c.transcript || c.mediaType === 'audio' || c.mediaType === 'voice'));
}
const VOICE_CORRECTION_MSG = 'E07（語音糾偏必問不猜）：這則是語音轉文字訊息，若上下文接不上、詞不達意、詞彙陌生、邏輯反常，四種情況任一出現就主動問「您說的是『XXXX』嗎？」，確認後再處理，不照字面瞎猜。';

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;
  if (!event.context || typeof event.context !== 'object') return;

  const text = extractText(event);
  const isVoice = isVoiceMessage(event.context);
  const agentId = resolveAgentId(event);

  // 抓不到文字、也不是語音訊息：dump 結構供精準化，靜默退出（不壞事）
  if (!text && !isVoice) { probeDump(event, ''); return; }

  const hits = [];
  if (text) {
    for (const r of RULES) {
      // 帶 scope 的規則只對指定 agent 生效；沒帶 scope = 全 agent 通用（原有行為不變）
      if (Array.isArray(r.scope) && !r.scope.includes(agentId)) continue;
      if (r.re.test(text)) hits.push('• ' + r.msg);
    }
  }
  if (isVoice) hits.push('• ' + VOICE_CORRECTION_MSG);

  if (hits.length === 0) return;

  // 命中時記錄一筆，確認 hook 真的有在運作 + 抓到文字
  probeDump(event, text);

  const injection = [
    '🌱 守則提醒（系統自動對照 trigger_index）：',
    ...hits,
    '（對照後再回應教練；引用守則前先查 特助心法.md 原文確認一字不差。）',
  ].join('\n');

  if (!event.context.inject) event.context.inject = [];
  if (Array.isArray(event.context.inject)) {
    event.context.inject.push({ role: 'system', content: injection });
  }
};

module.exports = handler;
module.exports.default = handler;

