      ctxKeys: Object.keys(c),
      messagesLen: Array.isArray(event.messages) ? event.messages.length : null,
      textPreview: matchedText ? String(matchedText).slice(0, 50) : '(抓不到文字)',
    };
    fs.appendFileSync(PROBE_LOG, JSON.stringify(info) + '\n');
  } catch (e) { /* silent */ }
}

