// rule-reminder 階段二驗證腳本（2026-08-05）
// 目的：證明 scope:['main'] 的三條新規則「只對教練自己的小龍蝦生效」，
//      且不影響原本全 agent 通用的規則。
// 用法：node ~/.openclaw/hooks/rule-reminder/test_scope.js

const handler = require('./handler.js');

function makeEvent({ text, agentId, sessionKey }) {
  const ctx = { text };
  if (agentId) ctx.agentId = agentId;
  if (sessionKey) ctx.sessionKey = sessionKey;
  return { type: 'message', action: 'preprocessed', context: ctx };
}

const CASES = [
  // --- 階段二三條新規則：只該對 main 生效 ---
  { name: 'E09 cron｜main（Telegram）', text: '提醒我每天早上八點量血壓', agentId: 'main', expect: 'E09' },
  { name: 'E09 cron｜龍蝦小助教（LINE default，sessionKey 含 main）', text: '幫我排程每週一自動跑', sessionKey: 'agent:main:line:group:C123', expect: 'E09' },
  { name: 'E09 cron｜bni_tainan（不該觸發）', text: '提醒我每天早上八點量血壓', agentId: 'bni_tainan', expect: null },
  { name: 'E09 cron｜jiaolian_thoughts（不該觸發）', text: '幫我定時提醒我開會', agentId: 'jiaolian_thoughts', expect: null },

  { name: 'E12 記憶｜main', text: '這個你記住，以後都這樣做', agentId: 'main', expect: 'E12' },
  { name: 'E12 記憶｜bni_tainan（不該觸發）', text: '這個你記住，以後都這樣做', agentId: 'bni_tainan', expect: null },

  { name: 'E08 引用｜main', text: '你之前說過這件事已經做完了', agentId: 'main', expect: 'E08' },
  { name: 'E08 引用｜bni_tainan（不該觸發）', text: '守則第13條是什麼', agentId: 'bni_tainan', expect: null },

  // --- 原有全 agent 通用規則：不能被這次改動弄壞 ---
  { name: '守則#04｜main（既有規則不受影響）', text: '這個壞了，一直出錯', agentId: 'main', expect: '守則#04' },
  { name: '守則#04｜bni_tainan（既有規則仍要通用）', text: '這個壞了，一直出錯', agentId: 'bni_tainan', expect: '守則#04' },
  { name: '守則#12｜未知 agent 也要通用', text: '幫我複製貼上回傳給我', agentId: null, expect: '守則#12' },

  // --- 不該有任何反應的正常對話 ---
  { name: '普通閒聊｜main（不該注入）', text: '今天天氣真好', agentId: 'main', expect: null },
];

let pass = 0, fail = 0;
(async () => {
  for (const c of CASES) {
    const ev = makeEvent(c);
    await handler(ev);
    const injected = (ev.context.inject || []).map((i) => i.content).join('\n');
    // 期待有值 → 必須含該字樣；期待 null → 必須完全沒注入
    const ok = c.expect ? injected.includes(c.expect) : injected === '';
    if (ok) { pass++; console.log(`✅ ${c.name}`); }
    else {
      fail++;
      console.log(`❌ ${c.name}`);
      console.log(`   期待：${c.expect || '(完全不注入)'}`);
      console.log(`   實際：${injected ? injected.slice(0, 160).replace(/\n/g, ' / ') : '(沒有注入)'}`);
    }
  }
  console.log(`\n結果：${pass} 通過 / ${fail} 失敗（共 ${CASES.length} 項）`);
  process.exit(fail === 0 ? 0 : 1);
})();
